/* @lc app=leetcode id=3449 lang=kotlin */ class Solution { fun ok(p: IntArray, m: Int, x: Long): Boolean = p.indices.fold(Triple(m.toLong(), 0L, true)) { (rem, pre, good), i -> if (!good) Triple(rem, pre, good) else ((x + p[i] - 1) / p[i] - pre).let { k0 -> if (i == p.size - 1 && k0 <= 0) Triple(rem, pre, good) else maxOf(k0, 1L).let { k -> (rem - (2 * k - 1)).let { r2 -> Triple(r2, k - 1, r2 >= 0) } } } }.third fun maxScore(points: IntArray, m: Int): Long = generateSequence(0L to 2_000_000_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (ok(points, m, mid)) mid to hi else lo to mid - 1 } }.last().first }